namespace ghidra.app.plugin.core.debug.client.tracermi;





using ghidra.app.plugin.core.debug.client.tracermi.RmiClient;

public class RmiBatch : AutoCloseable {

	private RmiClient client;
	private volatile int refCount = 0;
	private List<RequestResult> futures = new();

	public RmiBatch(RmiClient client) {
		this.client = client;
	}

	public void inc() {
		refCount++;
	}

	public int dec() {
		return --refCount;
	}

	/* @Override */
	public void close() {
		try {
			client.endBatch(this);
		}
		catch (Exception e) when (e is InterruptedException or ExecutionException) {
			throw new RuntimeException(e);
		}
	}

	public void append(RequestResult f) {
		lock (futures) {
			futures.add(f);
		}
	}

	public List<object> results()
    {
		List<RequestResult> futures = futures();
		List<object> results = new(futures.size());
		foreach (RequestResult r in futures) {
			results.add(r.get());
		}
		return results;
	}

	public List<RequestResult> futures() {
		lock (futures) {
			return List.copyOf(futures);
		}
	}
}
